        return new Order(
            (string)$row['id'],
            $row['status'],
            $row['email']
        );
    }

    public function save(Order $order): void
    {
        $stmt = $this->pdo->prepare("UPDATE orders SET status = ? WHERE id = ?");
        $stmt->execute([$order->getStatus(), $order->getId()]);
    }
}
